def reflect_x(p):
    x, y = p
    return (4 - x, y)
def reflect_y(p):
    x, y = p
    return (x, 4 - y)
punch = (1, 1)
holes = {punch, reflect_x(punch), reflect_y(punch), reflect_x(reflect_y(punch))}
assert holes == {(1, 1), (3, 1), (1, 3), (3, 3)}
assert reflect_x((1, 2)) == (3, 2)
print(len(holes))
